/** 설명 한 묶음 — 목차와 지금 어디인지, 그리고 곁가지 스택 */
export type Trail = {
  /** 설명 전체의 제목 (예: "Hikari 커넥션 풀") */
  title: string
  /**
   * 주제 이름. 큰 주제는 "1" · "2" … 번호, 곁가지는 부모 이름 뒤에 글자를 붙인 "2a" · "2b".
   *
   * `/recall 2.3` 의 그 `2`, `/recall 2a.3` 의 그 `2a` 다. 제목에서 이름을 뽑아 봤지만
   * ("Hikari 커넥션 풀" → hikari) 제목에 따라 들쭉날쭉하고, 순한글 제목에서는 칠 만한 것이
   * 안 나온다. 곁가지도 번호를 받게 했더니 곁가지가 큰 주제 번호를 잡아먹어 1, 2 다음이
   * 4 가 됐다(2026-10-14). 큰 주제는 번호로 이어지고, 곁가지는 어디 붙었는지가 이름에 보인다.
   */
  id: string
  /** 제목에서 뽑은 이름. 번호 대신 쳐도 찾아 준다 — 기억나는 쪽으로 부르면 된다 */
  slug: string
  /** 목차 항목들. 순서가 곧 번호다 */
  items: string[]
  /** 지금 설명 중인 항목 (0부터). 아직 안 들어갔으면 -1 */
  cursor: number
  /** 끝낸 항목 번호들 */
  done: number[]
  /**
   * 항목별 본문 — 설명을 끝낼 때 그 글을 그대로 남긴다.
   * 나중에 그 번호를 부르면 다시 쓰지 않고 이걸 꺼낸다. 다시 쓰면 말이 달라진다.
   * 키는 항목 번호(0부터)를 문자열로 쓴다.
   */
  notes: Record<string, string>
  /**
   * 곁가지면 어디서 갈라졌는지 — 그 주제 이름과 항목(0부터).
   *
   * 곁가지도 주제 하나로 둔다. 예전에는 이름표만 쌓고 답은 버렸다(덮어쓸까 봐). 그러니
   * 곁가지 답은 다시 볼 길이 없었고, 닫으면 이름표마저 사라졌다(2026-10-14). 주제로 두면
   * 목차·본문 저장·/recall 이 고칠 것 없이 그대로 돈다.
   */
  parent?: { id: string; at: number }
  /** 마지막으로 손댄 때 (epoch ms). 오래된 주제를 골라내는 기준 */
  touchedAt: number
}

/**
 * 들고 있는 주제 전부.
 *
 * 하나만 들고 있으면 새 설명이 시작될 때마다 지난 것이 날아간다. 이 mod 의 쓸모가
 * "나중에 다시 보기" 라서 그건 반쪽이다 — 주제별로 따로 둔다.
 */
export type Trails = {
  /**
   * 자동으로 쌓을지. 기본은 꺼짐이다.
   *
   * 켜 두면 설명이 갈래질 때마다 끼어든다. 늘 필요한 것이 아니라 — 뭘 배우려고 들어온
   * 자리에서만 켜면 된다. 꺼져 있어도 이미 쌓인 것은 /recall 로 그대로 본다.
   */
  on: boolean
  /** 주제 이름("2" · "2a") → 그 주제의 목차 */
  byTopic: Record<string, Trail>
  /** 지금 보고 있는 주제 이름. 없으면 빈 문자열 */
  current: string
  /**
   * 다음에 내줄 큰 주제 번호. 지운 번호는 다시 쓰지 않는다 — 같은 번호가 다른 주제를 가리키면
   * 헷갈린다. 곁가지 글자는 여기서 세지 않고 지운 자리를 채운다(nextBranchId).
   */
  nextNo: number
  /** 목차를 접어 둔 주제 이름들 — 제목만 남기고 항목을 숨긴다 */
  collapsed: string[]
  /**
   * 오래됐다고 물어본 주제 이름들.
   *
   * 한 번 "두기" 를 고르면 다시 묻지 않는다. 켤 때마다 같은 것을 물으면 그게 더 성가시다.
   */
  kept: string[]
}

declare module 'claude-code' {
  interface PluginState {
    'learn-trail': { trails: Trails; armed: boolean }
  }
}
